mapper.select:
SELECT gs.goods_id AS goodsId, CAST(gs.goods_sku_id AS CHAR) AS roomCategoryProductId, gs.sku_name AS roomCategoryProductName, gs.selling_price_cent AS sellingPrice, gs.original_price_cent AS originalPrice, gm.settlement_price_cent AS settlementPrice, CASE WHEN gm.shelf_status = 'on_shelf' AND (gm.stock_mode = 'unlimited' OR gs.stock > 0) THEN 1 ELSE 0 END AS isCanBooking, gs.stock AS stock, CASE WHEN gm.stock_mode = 'unlimited' THEN 1 ELSE 0 END AS stockMode, CAST(( SELECT m.media_resource_id FROM goods_room_category_rel rel JOIN room_category_media m ON m.room_category_id = rel.room_category_id AND m.status = 1 WHERE rel.goods_id = gs.goods_id ORDER BY CASE WHEN m.scene_type = 'cover' THEN 0 ELSE 1 END, m.sort_no ASC, m.media_id ASC LIMIT 1 ) AS CHAR) AS photoMediaId, ( SELECT COALESCE(m.media_url, mr.url) FROM goods_room_category_rel rel JOIN room_category_media m ON m.room_category_id = rel.room_category_id AND m.status = 1 LEFT JOIN media_resource mr ON mr.media_resource_id = m.media_resource_id AND mr.is_deleted = 0 WHERE rel.goods_id = gs.goods_id ORDER BY CASE WHEN m.scene_type = 'cover' THEN 0 ELSE 1 END, m.sort_no ASC, m.media_id ASC LIMIT 1 ) AS photoMediaUrl, gs.sort_no AS seq FROM goods_sku gs JOIN goods_main gm ON gm.goods_id = gs.goods_id AND gm.is_deleted = 0 WHERE gs.is_deleted = 0 AND gs.status = 'published' AND gs.goods_id IN
#{goodsId}
ORDER BY gs.goods_id ASC, gs.sort_no ASC, gs.goods_sku_id ASC
